SELECT EXISTS (
SELECT 1
FROM TBL_SCHEDULE_EVNT se
JOIN TBL_CALENDAR_POSITION_EVNT cpe ON cpe.schedule_sq = se.schedule_sq
WHERE se.schedule_user_sq = #{userSq}
AND cpe.project_sq      = #{projectSq}
AND se.schedule_is_deleted_yn = 'N'
)

SELECT EXISTS (
SELECT 1
FROM TBL_SCHEDULE_EVNT se
JOIN TBL_CALENDAR_POSITION_EVNT cpe ON cpe.schedule_sq = se.schedule_sq
WHERE se.schedule_user_sq = #{userSq}
AND cpe.project_sq      = #{projectSq}
AND se.schedule_is_deleted_yn = 'Y'
)
